// Sets server-owned fields: id is generated by json-server, createdAt/updatedAt are set here, and
// completed defaults to false. Clients can never choose or change id or createdAt.

function idFromPath(path) {
  const match = /^\/todos\/([^/]+)/.exec(path ?? '');
  return match ? match[1] : undefined;
}

// db: { findById(id) } returning the stored todo or undefined.
function createStamp({ db, now = () => new Date() }) {
  return function stamp(req, res, next) {
    const method = req.method;
    if (method !== 'POST' && method !== 'PUT' && method !== 'PATCH') return next();

    const body = req.body && typeof req.body === 'object' ? req.body : {};
    req.body = body;
    const timestamp = now().toISOString();

    if (method === 'POST') {
      delete body.id;
      body.createdAt = timestamp;
      body.updatedAt = timestamp;
      if (body.completed === undefined) body.completed = false;
    } else if (method === 'PUT') {
      const existing = db.findById(idFromPath(req.path));
      delete body.id;
      delete body.createdAt;
      if (existing) {
        body.id = existing.id;
        body.createdAt = existing.createdAt;
      }
      if (body.completed === undefined) body.completed = false;
      body.updatedAt = timestamp;
    } else {
      delete body.id;
      delete body.createdAt;
      body.updatedAt = timestamp;
    }

    return next();
  };
}

module.exports = { createStamp };
